changeSet.sql:
CREATE TABLE IF NOT EXISTS "user".user_scoring (
    id            UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    scoring_id    TEXT,           -- provider scoring id (integration plum_scoring id)
    scoring_type  TEXT,           -- HESAP | KATM | PAYMENT (karta skoringi)
    requester_in  TEXT,           -- kim so'radi (PINFL/STIR)
    user_in       TEXT,           -- kim scoring qilindi (karta egasi PINFL/STIR)
    created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_user_scoring_requester
    ON "user".user_scoring (requester_in, scoring_type);
